85: const tid = (page, id) => page.getByTestId(id);
86: async function go(page, navId) {
87:   await tid(page, navId).first().click({ timeout: T });
88:   await sleep(350);
89: }
90: async function onScreens(page, id, screens = ['nav-today', 'nav-settings', 'nav-week']) {
91:   for (const s of screens) {
92:     try {
93:       await go(page, s);
94:     } catch {
95:       continue;
96:     }
97:     if ((await tid(page, id).count()) > 0) return s;
98:   }
99:   return null;
100: }
101: const bodyText = (page) => page.evaluate(() => document.body.innerText.replace(/\s+/g, ' ').trim());
102: const reload = async (page) => {
103:   await page.reload({ waitUntil: 'load' });
104:   await sleep(600);
105: };
106: const pressed = async (loc) => {
107:   const v = (await loc.getAttribute('aria-pressed')) ?? (await loc.getAttribute('aria-checked'));
108:   return v === 'true';
109: };
110: const progress = async (page) => {
111:   const txt = (await tid(page, 'progress').first().innerText()).replace(/\s+/g, ' ');
112:   const m = txt.match(/(\d+)\s*von\s*(\d+)/i);
113:   assert(m, `Fortschritt "${txt}" passt nicht zu "X von Y"`);
114:   return { done: +m[1], total: +m[2], txt };
115: };
116: // effektive Hintergrundluminanz (0 = schwarz, 1 = weiß) links in der Bildschirmmitte
117: const luminance = (page) =>
118:   page.evaluate(() => {
119:     const c = document.createElement('canvas');
120:     c.width = c.height = 1;
121:     const g = c.getContext('2d', { willReadFrequently: true });
122:     const chain = [];
123:     for (let el = document.elementFromPoint(2, window.innerHeight / 2); el; el = el.parentElement) chain.push(el);
124:     // Hintergrund von <body> wird vom Browser auf die ganze Fläche übertragen, auch wenn der Punkt unter dem Body liegt
125:     chain.push(document.body, document.documentElement);
126:     for (const el of chain) {
127:       const col = getComputedStyle(el).backgroundColor;
128:       g.clearRect(0, 0, 1, 1);
129:       g.fillStyle = '#000';
130:       g.fillStyle = col;
131:       g.fillRect(0, 0, 1, 1);
132:       const [r, gr, b, a] = g.getImageData(0, 0, 1, 1).data;
133:       if (a > 250) return (0.2126 * r + 0.7152 * gr + 0.0722 * b) / 255;
134:     }
135:     return 1;
136:   });
