309: await check('Inhalt, der über den Bildschirm hinausragt, lässt sich scrollen', async () => {
310:   const problems = [];
311:   for (const n of ['nav-today', 'nav-week', 'nav-settings']) {
312:     await go(page, n);
313:     const overflowing = await page.evaluate(() => {
314:       let maxBottom = 0;
315:       for (const el of document.querySelectorAll('body *')) {
316:         if (el.children.length) continue;
317:         const r = el.getBoundingClientRect();
318:         const cs = getComputedStyle(el);
319:         if (!r.width || !r.height || cs.position === 'fixed' || cs.visibility === 'hidden') continue;
320:         if (!(el.textContent || '').trim() && el.tagName !== 'svg') continue;
321:         maxBottom = Math.max(maxBottom, r.bottom);
322:       }
323:       return Math.max(maxBottom, document.scrollingElement.scrollHeight) > window.innerHeight + 5;
324:     });
325:     if (!overflowing) continue;
326:     const snap = () =>
327:       page.evaluate(() => window.scrollY + [...document.querySelectorAll('*')].reduce((s, e) => s + e.scrollTop, 0));
328:     const before = await snap();
329:     await page.mouse.move(VIEWPORT.width / 2, VIEWPORT.height / 2);
330:     await page.mouse.wheel(0, 1500);
331:     await sleep(300);
332:     if ((await snap()) === before) problems.push(n);
333:   }
334:   assert(problems.length === 0, `Inhalt wird abgeschnitten und lässt sich nicht scrollen auf: ${problems.join(', ')}`);
