381:   const res = await page.request.get(href);
382:   assert(res.ok(), `Manifest nicht ladbar (HTTP ${res.status()})`);
383:   const m = await res.json();
384:   assert(m.name || m.short_name, 'Manifest ohne name');
385:   assert(['standalone', 'fullscreen', 'minimal-ui'].includes(m.display), `display="${m.display}"`);
386:   const sizes = (m.icons ?? []).flatMap((i) => String(i.sizes).split(/\s+/).map((s) => ({ s, i })));
387:   const icon = (px) => sizes.find((x) => x.s === `${px}x${px}`)?.i;
388:   assert(icon(192), 'Kein Icon 192x192 im Manifest');
389:   assert(icon(512), 'Kein Icon 512x512 im Manifest');
390:   const types = [];
391:   for (const px of [192, 512]) {
392:     const r = await page.request.get(new URL(icon(px).src, href).href);
393:     assert(r.ok(), `Icon ${px} nicht ladbar (HTTP ${r.status()})`);
394:     assert((r.headers()['content-type'] ?? '').startsWith('image/'), `Icon ${px} hat Content-Type ${r.headers()['content-type']}`);
395:     const len = (await r.body()).length;
396:     assert(len > 100, `Icon ${px} ist praktisch leer (${len} Bytes)`);
397:     types.push(r.headers()['content-type']);
