@import "tailwindcss";

/* Farb- und Font-Variablen - minimalistisches, elegantes Design */
@theme {
  --font-sans: -apple-system, BlinkMacSystemFont, "SF Pro Display", "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --font-serif: "Lyon Text", "Newsreader", "Playfair Display", serif;

  /* Warm monochrome Palette */
  --color-background: #F7F6F3;
  --color-surface: #FFFFFF;
  --color-surface-hover: #F9F9F8;
  --color-text: #2F3437;
  --color-text-secondary: #787774;
  --color-border: #EAEAEA;
  --color-accent: #346538;

  /* Muted Pastels für Habit-Farben */
  --color-pastel-red: #FDEBEC;
  --color-pastel-red-text: #9F2F2D;
  --color-pastel-blue: #E1F3FE;
  --color-pastel-blue-text: #1F6C9F;
  --color-pastel-green: #EDF3EC;
  --color-pastel-green-text: #346538;
  --color-pastel-yellow: #FBF3DB;
  --color-pastel-yellow-text: #956400;

  /* Radien und Schatten (sehr dezent) */
  --radius-soft: 24px;
  --shadow-soft: 0 2px 8px 0 rgba(0, 0, 0, 0.04);
}

:root {
  font-family: var(--font-sans);
  color: var(--color-text);
  background: var(--color-background);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* Mobile first: schmale Spalte auf Desktop */
#root {
  min-height: 100vh;
  background: var(--color-background);
}

/* Container für zentrierte, schmale Spalte auf Desktop */
.app-container {
  max-width: 480px;
  margin: 0 auto;
  min-height: 100vh;
  background: var(--color-background);
  position: relative;
}

/* Tab-Navigation (Bottom Navigation) */
.bottom-nav {
  position: fixed;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 100%;
  max-width: 480px;
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
  display: flex;
  justify-content: space-around;
  padding: 16px 0;
  box-shadow: 0 -2px 8px 0 rgba(0, 0, 0, 0.04);
}

.nav-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  border-radius: 12px;
  min-width: 60px;
  min-height: 56px;
  font-size: 11px;
  font-weight: 500;
  color: var(--color-text-secondary);
  transition: all 0.2s ease;
}

.nav-item:hover {
  background: var(--color-surface-hover);
}

.nav-item.active {
  color: var(--color-accent);
  font-weight: 600;
}

/* Hauptinhalt mit ausreichend Padding für Bottom-Navigation */
.main-content {
  padding-bottom: 100px;
}

/* Karten-Stil */
.card {
  background: var(--color-surface);
  border-radius: var(--radius-soft);
  box-shadow: var(--shadow-soft);
  padding: 24px;
  margin-bottom: 16px;
}

/* Typografie */
h1, h2, h3 {
  font-family: var(--font-sans);
  font-weight: 600;
  color: var(--color-text);
  line-height: 1.3;
}

h1 { font-size: 28px; margin: 0 0 16px; }
h2 { font-size: 20px; margin: 0 0 12px; }
h3 { font-size: 16px; margin: 0 0 8px; }

p {
  margin: 0 0 8px;
  color: var(--color-text-secondary);
  font-size: 14px;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 12px 24px;
  border-radius: 12px;
  font-size: 15px;
  font-weight: 500;
  font-family: var(--font-sans);
  cursor: pointer;
  transition: all 0.2s ease;
  border: none;
}

.btn-primary {
  background: var(--color-text);
  color: #FFFFFF;
}

.btn-primary:hover {
  background: #1a1d1f;
}

.btn-icon {
  padding: 12px;
  min-width: 48px;
  min-height: 48px;
}

/* Form Elements */
input, select {
  width: 100%;
  padding: 12px 16px;
  border-radius: 12px;
  border: 1px solid var(--color-border);
  background: var(--color-surface);
  font-size: 15px;
  font-family: var(--font-sans);
  color: var(--color-text);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

input:focus, select:focus {
  outline: none;
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px rgba(52, 101, 56, 0.1);
}

/* Focus-Styles für Tastatur-Navigation */
:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

/* Scrollbar (_subtil) */
::-webkit-scrollbar {
  width: 6px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background: var(--color-border);
  border-radius: 3px;
}

/* Dark Mode */
@media (prefers-color-scheme: dark) {
  :root {
    --color-background: #1a1b1d;
    --color-surface: #25272a;
    --color-surface-hover: #2d2f33;
    --color-text: #E5E7EB;
    --color-text-secondary: #9CA3AF;
    --color-border: #373A40;
    --color-accent: #4B9E5F;
  }

  .bottom-nav {
    background: var(--color-surface);
    border-top: 1px solid var(--color-border);
    box-shadow: 0 -2px 8px 0 rgba(0, 0, 0, 0.3);
  }

  input, select {
    background: var(--color-surface);
    border-color: var(--color-border);
    color: var(--color-text);
  }
}

/* Motion-Reduction */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* Leerzustand */
.empty-state {
  text-align: center;
  padding: 64px 24px;
  color: var(--color-text-secondary);
}

.empty-state p {
  margin: 8px 0;
}

// db.ts – IndexedDB über idb für Habit & Stimmungs-Tracker
import { openDB } from 'idb'

const DB_NAME = 'rhythm-db'
const DB_VERSION = 1

// Typen
export type Mood = {
  id: string
  date: string // ISO Date string (YYYY-MM-DD)
  value: number // 1-5
  note?: string
  timestamp: number
}

export type Habit = {
  id: string
  name: string
  emoji: string
  color: string
  createdAt: number
}

export type HabitStatus = {
  id: string
  habitId: string
  date: string
  completed: boolean
  timestamp: number
}

export type Theme = 'light' | 'dark' | 'system'
export type SystemTheme = 'light' | 'dark'

// Initialer Stimmungs-Emoji-Satz
export const MOOD_EMOJIS = ['😡', '😢', '😐', '🙂', '😄']
export const MOOD_COLORS = ['#9F2F2D', '#1F6C9F', '#956400', '#346538', '#2F3437']

// Hole heute's Date string
export const getTodayString = (): string => {
  return new Date().toISOString().split('T')[0]
}

// Hole gestrigen Date string
export const getYesterdayString = (): string => {
  const date = new Date()
  date.setDate(date.getDate() - 1)
  return date.toISOString().split('T')[0]
}

//Öffne DB
export const openRhythmDB = async () => {
  return openDB(DB_NAME, DB_VERSION, {
    upgrade(db) {
      // Habits Store
      if (!db.objectStoreNames.contains('habits')) {
        const habitsStore = db.createObjectStore('habits', { keyPath: 'id' })
        habitsStore.createIndex('createdAt', 'createdAt')
      }

      // HabitStatus Store
      if (!db.objectStoreNames.contains('habitStatus')) {
        const statusStore = db.createObjectStore('habitStatus', { keyPath: 'id' })
        statusStore.createIndex('habitId_date', ['habitId', 'date'])
        statusStore.createIndex('date', 'date')
      }

      // Moods Store
      if (!db.objectStoreNames.contains('moods')) {
        const moodsStore = db.createObjectStore('moods', { keyPath: 'id' })
        moodsStore.createIndex('date', 'date')
      }

      // Settings Store
      if (!db.objectStoreNames.contains('settings')) {
        const settingsStore = db.createObjectStore('settings', { keyPath: 'key' })
      }
    }
  })
}

// Helper: UUID generieren
export const generateId = (): string => {
  return crypto.randomUUID()
}

// Settings
export const getTheme = async (): Promise<Theme> => {
  try {
    const db = await openRhythmDB()
    const value = await db.get('settings', 'theme')
    return value?.value || 'system'
  } catch {
    return 'system'
  }
}

export const setTheme = async (theme: Theme) => {
  const db = await openRhythmDB()
  await db.put('settings', { key: 'theme', value: theme })
}

export const getSystemTheme = (): SystemTheme => {
  if (typeof window === 'undefined') return 'light'
  return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'
}

// Habits
export const getAllHabits = async (): Promise<Habit[]> => {
  const db = await openRhythmDB()
  return await db.getAll('habits')
}

export const addHabit = async (habit: Omit<Habit, 'id' | 'createdAt'>): Promise<string> => {
  const db = await openRhythmDB()
  const id = generateId()
  const newHabit = { ...habit, id, createdAt: Date.now() }
  await db.add('habits', newHabit)
  return id
}

export const updateHabit = async (habit: Habit): Promise<void> => {
  const db = await openRhythmDB()
  await db.put('habits', habit)
}

export const deleteHabit = async (id: string): Promise<void> => {
  const db = await openRhythmDB()
  await db.delete('habits', id)
  // Also delete status entries
  const status = await db.getAll('habitStatus')
  const toDelete = status.filter(s => s.habitId === id).map(s => s.id)
  for (const id of toDelete) {
    await db.delete('habitStatus', id)
  }
}

// Habit Status
export const getHabitStatus = async (habitId: string, date: string): Promise<HabitStatus | undefined> => {
  const db = await openRhythmDB()
  const tx = db.transaction('habitStatus', 'readonly')
  const store = tx.objectStore('habitStatus')
  const index = store.index('habitId_date')
  const key = [habitId, date]
  const value = await index.get(key)
  return value
}

export const setHabitStatus = async (habitId: string, date: string, completed: boolean): Promise<void> => {
  const db = await openRhythmDB()
  const existing = await getHabitStatus(habitId, date)

  if (existing) {
    await db.put('habitStatus', {
      ...existing,
      completed,
      timestamp: Date.now()
    })
  } else {
    await db.add('habitStatus', {
      id: generateId(),
      habitId,
      date,
      completed,
      timestamp: Date.now()
    })
  }
}

// Streaks berechnen
export const calculateStreaks = async (habitId: string): Promise<{ current: number; longest: number }> => {
  const db = await openRhythmDB()
  const status = await db.getAll('habitStatus')

  const habitStatuses = status
    .filter(s => s.habitId === habitId && s.completed)
    .map(s => s.date)
    .sort()

  if (habitStatuses.length === 0) return { current: 0, longest: 0 }

  let current = 0
  let longest = 0
  let streak = 0
  const today = getTodayString()
  const yesterday = getYesterdayString()

  // Aktuelle Serie berechnen (ab heute oder gestern rückwärts)
  const todayIndex = habitStatuses.indexOf(today)
  const yesterdayIndex = habitStatuses.indexOf(yesterday)

  if (todayIndex !== -1 || yesterdayIndex !== -1) {
    // Wir sind in einer aktiven Serie
    let checkDate = today
    if (todayIndex === -1) checkDate = yesterday

    while (true) {
      if (habitStatuses.includes(checkDate)) {
        streak++
        const date = new Date(checkDate)
        date.setDate(date.getDate() - 1)
        checkDate = date.toISOString().split('T')[0]
      } else {
        break
      }
    }
    current = streak
  }

  // Längste Serie berechnen
  let maxStreak = 0
  let currentChain = 0
  let prevDate: string | null = null

  for (const date of habitStatuses) {
    if (prevDate) {
      const prev = new Date(prevDate)
      const curr = new Date(date)
      const diff = (curr.getTime() - prev.getTime()) / (1000 * 60 * 60 * 24)

      if (diff === 1) {
        currentChain++
      } else {
        maxStreak = Math.max(maxStreak, currentChain)
        currentChain = 1
      }
    } else {
      currentChain = 1
    }
    prevDate = date
  }
  maxStreak = Math.max(maxStreak, currentChain)

  return { current, longest: maxStreak }
}

// Moods
export const getMoodForDate = async (date: string): Promise<Mood | undefined> => {
  const db = await openRhythmDB()
  return await db.get('moods', date)
}

export const setMood = async (date: string, value: number, note?: string): Promise<void> => {
  const db = await openRhythmDB()
  const existing = await db.get('moods', date)

  if (existing) {
    await db.put('moods', {
      ...existing,
      value,
      note,
      timestamp: Date.now()
    })
  } else {
    await db.add('moods', {
      id: date,
      date,
      value,
      note,
      timestamp: Date.now()
    })
  }
}

export const getMoodHistory = async (days: number): Promise<Mood[]> => {
  const db = await openRhythmDB()
  const allMoods = await db.getAll('moods')

  const cutoff = new Date()
  cutoff.setDate(cutoff.getDate() - days)

  return allMoods
    .filter(m => new Date(m.date) >= cutoff)
    .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime())
}

// Heute's Habits mit Status
export const getTodayHabits = async (): Promise<(Habit & { completed: boolean })[]> => {
  const db = await openRhythmDB()
  const habits = await db.getAll('habits')
  const today = getTodayString()

  const results: (Habit & { completed: boolean })[] = []

  for (const habit of habits) {
    const status = await getHabitStatus(habit.id, today)
    results.push({
      ...habit,
      completed: status?.completed || false
    })
  }

  return results
}

// Woche's Daten für Chart
export const getWeekData = async (): Promise<{ date: string; completed: number; mood: number | null }[]> => {
  const db = await openRhythmDB()
  const habits = await db.getAll('habits')
  const today = new Date()
  const weekData: { [key: string]: { completed: number; mood: number | null } } = {}

  // Letzte 7 Tage initialisieren
  for (let i = 6; i >= 0; i--) {
    const date = new Date()
    date.setDate(date.getDate() - i)
    const dateStr = date.toISOString().split('T')[0]
    weekData[dateStr] = { completed: 0, mood: null }
  }

  // Status für alle Habits der letzten 7 Tage zählen
  const status = await db.getAll('habitStatus')
  for (const s of status) {
    if (weekData[s.date] !== undefined && s.completed) {
      weekData[s.date].completed++
    }
  }

  // Moods für die letzten 7 Tage laden
  const moods = await db.getAll('moods')
  for (const m of moods) {
    if (weekData[m.date] !== undefined) {
      weekData[m.date].mood = m.value
    }
  }

  return Object.entries(weekData)
    .map(([date, data]) => ({ date, ...data }))
    .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime())
}

