import { type ReactNode } from 'react'
import { useNavigate, useLocation } from 'react-router-dom'
import './App.css'

export default function AppLayout({ children }: { children: ReactNode }) {
  const navigate = useNavigate()
  const location = useLocation()

  const navItems = [
    { id: 'nav-today', label: 'Heute', path: '/' },
    { id: 'nav-week', label: 'Woche', path: '/week' },
    { id: 'nav-settings', label: 'Einstellungen', path: '/settings' },
  ]

  const currentPath = location.pathname

  return (
    <div className="app-container">
      <main className="main-content">
        {children}
      </main>

      <nav className="bottom-nav" role="navigation" aria-label="Hauptnavigation">
        {navItems.map((item) => (
          <button
            key={item.id}
            data-testid={item.id}
            className={`nav-item ${currentPath === item.path ? 'active' : ''}`}
            onClick={() => navigate(item.path)}
            aria-label={item.label}
          >
            {item.label}
          </button>
        ))}
      </nav>
    </div>
  )
}

import { useState, useEffect, useCallback } from 'react'
import { useNavigate } from 'react-router-dom'
import { getTodayHabits, setHabitStatus, calculateStreaks } from '../db'
import type { Habit } from '../db'
import './App.css'

export default function TodayScreen() {
  const navigate = useNavigate()
  const [habits, setHabits] = useState<(Habit & { completed: boolean })[]>([])
  const [loading, setLoading] = useState(true)

  // Aktuelle Habits laden
  const loadHabits = useCallback(async () => {
    try {
      const loadedHabits = await getTodayHabits()
      setHabits(loadedHabits)
    } catch (error) {
      console.error('Fehler beim Laden der Habits:', error)
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    loadHabits()
  }, [loadHabits])

  // Fortschritt berechnen
  const progress = habits.reduce((acc, habit) => acc + (habit.completed ? 1 : 0), 0)
  const total = habits.length

  // Habit abhaken/abhaken
  const toggleHabit = async (habitId: string, currentStatus: boolean) => {
    try {
      const date = new Date().toISOString().split('T')[0]
      await setHabitStatus(habitId, date, !currentStatus)
      await loadHabits()
    } catch (error) {
      console.error('Fehler beim Ändern des Status:', error)
    }
  }

  // Navigiere zur Einstellungen zum Hinzufügen
  const handleAddHabit = () => {
    navigate('/settings')
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="text-text-secondary">Laden...</div>
      </div>
    )
  }

  return (
    <div className="p-4 space-y-6">
      {/* Header mit Datum und Fortschritt */}
      <header className="mb-6">
        <div className="text-4xl font-bold text-text mb-2">
          {new Date().toLocaleDateString('de-DE', { 
            weekday: 'long', 
            day: 'numeric', 
            month: 'long' 
          })}
        </div>
        <div 
          data-testid="progress"
          className="text-2xl font-semibold text-accent"
        >
          {total > 0 ? `${progress} von ${total}` : '0 von 0'}
        </div>
      </header>

      {/* Habits Liste */}
      <div className="space-y-3">
        {habits.length === 0 ? (
          <div className="empty-state">
            <div className="text-6xl mb-4">✊</div>
            <h3 className="text-xl font-semibold mb-2">Keine Habits</h3>
            <p>Erstelle dein erstes Habit und starte durch!</p>
            <button
              data-testid="habit-add"
              onClick={handleAddHabit}
              className="mt-6 btn btn-primary"
            >
              + Habit hinzufügen
            </button>
          </div>
        ) : (
          habits.map((habit) => (
            <HabitItem
              key={habit.id}
              habit={habit}
              onToggle={() => toggleHabit(habit.id, habit.completed)}
            />
          ))
        )}
      </div>

      {/* Add Habit Button */}
      <button
        data-testid="habit-add"
        onClick={handleAddHabit}
        className="w-full btn btn-primary"
      >
        + weiteres Habit
      </button>
    </div>
  )
}

// Einzelnes Habit Item
interface HabitItemProps {
  habit: Habit & { completed: boolean }
  onToggle: () => void
}

function HabitItem({ habit, onToggle }: HabitItemProps) {
  const [streaks, setStreaks] = useState({ current: 0, longest: 0 })

  useEffect(() => {
    calculateStreaks(habit.id).then(setStreaks)
  }, [habit.id, habit.completed])

  // Farben für Habit
  const getColorClasses = (color: string) => {
    switch (color) {
      case 'red': return 'text-[#9F2F2D] bg-[#FDEBEC]'
      case 'blue': return 'text-[#1F6C9F] bg-[#E1F3FE]'
      case 'green': return 'text-[#346538] bg-[#EDF3EC]'
      case 'yellow': return 'text-[#956400] bg-[#FBF3DB]'
      default: return 'text-text-secondary bg-border'
    }
  }

  //const colorClasses = getColorClasses(habit.color)

  return (
    <div
      data-testid="habit-item"
      className={`flex items-center justify-between p-4 rounded-3xl border-2 transition-all duration-300 ${
        habit.completed 
          ? 'border-border bg-surface opacity-60' 
          : 'border-transparent bg-surface hover:shadow-soft'
      }`}
    >
      <div className="flex items-center gap-4">
        {/* Habit Icon/Emoji */}
        <div className="text-3xl select-none">{habit.emoji}</div>

        <div>
          <div className="font-semibold text-lg">{habit.name}</div>
          <div 
            data-testid="habit-streak"
            className="text-sm text-text-secondary flex items-center gap-2"
          >
            <span className="flex items-center gap-1">
              🔥 {streaks.current}
            </span>
            <span className="opacity-50">•</span>
            <span className="flex items-center gap-1">
              🏆 {streaks.longest}
            </span>
          </div>
        </div>
      </div>

      {/* Toggle Button */}
      <button
        data-testid="habit-toggle"
        onClick={onToggle}
        aria-pressed={habit.completed}
        className={`w-14 h-8 rounded-full p-1 transition-all duration-300 ${
          habit.completed ? 'bg-accent' : 'bg-border'
        }`}
      >
        <div 
          className={`w-6 h-6 rounded-full bg-white shadow-md transition-transform duration-300 ${
            habit.completed ? 'translate-x-6' : 'translate-x-0'
          }`}
        />
      </button>
    </div>
  )
}

import { useState, useEffect, useCallback } from 'react'
import { getWeekData, setMood } from '../db'
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts'
import type { Mood } from '../db'
import './App.css'

export default function WeekScreen() {
  const [data, setData] = useState<{ date: string; completed: number; mood: number | null }[]>([])
  const [loading, setLoading] = useState(true)

  // Woche's Daten laden
  const loadData = useCallback(async () => {
    try {
      const weekData = await getWeekData()
      setData(weekData)
    } catch (error) {
      console.error('Fehler beim Laden der Woche:', error)
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    loadData()
  }, [loadData])

  // Mood setzen
  const handleMoodSelect = async (value: number) => {
    try {
      const date = new Date().toISOString().split('T')[0]
      await setMood(date, value)
      await loadData()
    } catch (error) {
      console.error('Fehler beim Setzen der Stimmung:', error)
    }
  }

  // Heute's Stimmung
  const todayMood = data.length > 0 ? data[data.length - 1]?.mood : null

  // Datum formatieren
  const formatDate = (dateStr: string) => {
    const date = new Date(dateStr)
    return date.toLocaleDateString('de-DE', { weekday: 'short' })
  }

  // Mood Farbe
  const getMoodColor = (value: number) => {
    const colors = ['#D62828', '#F77F00', '#FCAF45', '#2A9D8F', '#2A9D8F']
    return colors[value - 1]
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="text-text-secondary">Laden...</div>
      </div>
    )
  }

  return (
    <div className="p-4 space-y-6">
      <h2 className="text-2xl font-bold mb-6">Woche</h2>

      {/* Heute's Stimmung */}
      <section>
        <h3 className="text-lg font-semibold mb-3">Heute's Stimmung</h3>
        <div className="flex justify-between items-center p-4 rounded-3xl bg-surface">
          <div className="flex flex-col gap-1">
            <p className="text-sm text-text-secondary">Wie fühlst du dich heute?</p>
            <div className="flex gap-2" role="radiogroup" aria-label="Stimmungswahl">
              {[1, 2, 3, 4, 5].map((value) => (
                <button
                  key={value}
                  data-testid={`mood-${value}`}
                  role="radio"
                  aria-checked={todayMood === value}
                  onClick={() => handleMoodSelect(value)}
                  className={`w-12 h-12 rounded-2xl flex items-center justify-center text-2xl transition-all duration-200 ${
                    todayMood === value 
                      ? `scale-110 ring-2 ring-offset-2 ring-accent` 
                      : 'hover:scale-105'
                  }`}
                  style={{
                    backgroundColor: todayMood === value ? getMoodColor(value) : '',
                    color: todayMood === value ? '#FFFFFF' : ''
                  }}
                >
                  {['😡', '😢', '😐', '🙂', '😄'][value - 1]}
                </button>
              ))}
            </div>
          </div>
        </div>
      </section>

      {/* Chart */}
      <section data-testid="week-chart">
        <h3 className="text-lg font-semibold mb-3">Letzte 7 Tage</h3>
        <div className="rounded-3xl bg-surface p-4">
          {data.length === 0 || data.every(d => d.completed === 0 && d.mood === null) ? (
            <div className="empty-state py-8">
              <p>Noch keine Daten für dieses Wochen</p>
            </div>
          ) : (
            <ResponsiveContainer width="100%" height={250}>
              <BarChart data={data} margin={{ top: 20, right: 30, left: 20, bottom: 40 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="rgba(0,0,0,0.1)" />
                <XAxis 
                  dataKey="date" 
                  tickFormatter={formatDate}
                  axisLine={false}
                  tickLine={false}
                  dy={10}
                />
                <YAxis 
                  axisLine={false}
                  tickLine={false}
                  domain={[0, 'auto']}
                  tickCount={6}
                />
                <Tooltip 
                  contentStyle={{ 
                    borderRadius: '12px', 
                    border: 'none',
                    boxShadow: '0 4px 12px rgba(0,0,0,0.1)'
                  }}
                  cursor={{ fill: 'rgba(0,0,0,0.05)' }}
                />
                <Legend />
                <Bar 
                  dataKey="completed" 
                  name="Erledigte Habits" 
                  fill="#346538"
                  radius={[8, 8, 0, 0]}
                  barSize={24}
                />
              </BarChart>
            </ResponsiveContainer>
          )}
        </div>
      </section>
    </div>
  )
}

import { useState, useEffect, useCallback } from 'react'
import { getAllHabits, addHabit, deleteHabit, getTheme, setTheme, MOOD_EMOJIS, MOOD_COLORS } from '../db'
import type { Habit, Theme } from '../db'
import './App.css'

export default function SettingsScreen() {
  const [habits, setHabits] = useState<Habit[]>([])
  const [loading, setLoading] = useState(true)

  // Add Habit Modal
  const [showAddModal, setShowAddModal] = useState(false)
  const [newHabitName, setNewHabitName] = useState('')
  const [selectedEmoji, setSelectedEmoji] = useState(MOOD_EMOJIS[0])
  const [selectedColor, setSelectedColor] = useState('green')

  // Theme
  const [theme, setThemeState] = useState<Theme>('system')
  const [isDark, setIsDark] = useState(false)

  // Habits laden
  const loadHabits = useCallback(async () => {
    try {
      const loadedHabits = await getAllHabits()
      setHabits(loadedHabits)
    } catch (error) {
      console.error('Fehler beim Laden der Habits:', error)
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    loadHabits()

    // Theme laden
    const loadTheme = async () => {
      const savedTheme = await getTheme()
      setThemeState(savedTheme)
      updateTheme(savedTheme)
    }
    loadTheme()

    // System theme ändern
    const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)')
    const updateThemeFromSystem = () => {
      if (theme === 'system') {
        updateTheme('system')
      }
    }
    mediaQuery.addEventListener('change', updateThemeFromSystem)

    return () => mediaQuery.removeEventListener('change', updateThemeFromSystem)
  }, [theme, loadHabits])

  // Theme anpassen
  const updateTheme = useCallback((t: Theme) => {
    const systemIsDark = window.matchMedia('(prefers-color-scheme: dark)').matches
    const dark = t === 'dark' || (t === 'system' && systemIsDark)
    setIsDark(dark)

    if (dark) {
      document.documentElement.classList.add('dark')
    } else {
      document.documentElement.classList.remove('dark')
    }
  }, [])

  const handleThemeChange = async (newTheme: Theme) => {
    await setTheme(newTheme)
    setThemeState(newTheme)
    updateTheme(newTheme)
  }

  // Habit hinzufügen
  const handleAddHabit = async () => {
    if (!newHabitName.trim()) return

    try {
      await addHabit({
        name: newHabitName,
        emoji: selectedEmoji,
        color: selectedColor
      })
      setNewHabitName('')
      setShowAddModal(false)
      await loadHabits()
    } catch (error) {
      console.error('Fehler beim Hinzufügen:', error)
    }
  }

  // Habit löschen
  const handleDeleteHabit = async (id: string) => {
    if (!confirm('Möchtest du dieses Habit wirklich löschen?')) return

    try {
      await deleteHabit(id)
      await loadHabits()
    } catch (error) {
      console.error('Fehler beim Löschen:', error)
    }
  }

  // Farbe auswählen
  const colorOptions = [
    { name: 'red', emoji: '🔴' },
    { name: 'blue', emoji: '🔵' },
    { name: 'green', emoji: '🟢' },
    { name: 'yellow', emoji: '🟡' }
  ]

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="text-text-secondary">Laden...</div>
      </div>
    )
  }

  return (
    <div className="p-4 space-y-6">
      <h2 className="text-2xl font-bold">Einstellungen</h2>

      {/* Theme Toggle */}
      <section>
        <h3 className="text-lg font-semibold mb-3">Darstellung</h3>
        <div className="rounded-3xl bg-surface p-4">
          <div className="flex items-center justify-between mb-4">
            <span className="text-sm font-medium">Dark Mode</span>
            <button
              data-testid="theme-toggle"
              onClick={() => handleThemeChange(isDark ? 'light' : 'dark')}
              className={`w-14 h-8 rounded-full p-1 transition-all duration-300 ${
                isDark ? 'bg-accent' : 'bg-border'
              }`}
            >
              <div 
                className={`w-6 h-6 rounded-full bg-white shadow-md transition-transform duration-300 ${
                  isDark ? 'translate-x-6' : 'translate-x-0'
                }`}
              />
            </button>
          </div>

          <div className="flex gap-2">
            <button
              onClick={() => handleThemeChange('light')}
              className={`flex-1 py-2 px-4 rounded-xl text-sm font-medium transition-colors ${
                theme === 'light' ? 'bg-accent text-white' : 'bg-border text-text'
              }`}
            >
              Hell
            </button>
            <button
              onClick={() => handleThemeChange('dark')}
              className={`flex-1 py-2 px-4 rounded-xl text-sm font-medium transition-colors ${
                theme === 'dark' ? 'bg-accent text-white' : 'bg-border text-text'
              }`}
            >
              Dunkel
            </button>
            <button
              onClick={() => handleThemeChange('system')}
              className={`flex-1 py-2 px-4 rounded-xl text-sm font-medium transition-colors ${
                theme === 'system' ? 'bg-accent text-white' : 'bg-border text-text'
              }`}
            >
              System
            </button>
          </div>
        </div>
      </section>

      {/* Habits verwalten */}
      <section>
        <h3 className="text-lg font-semibold mb-3">Habits verwalten</h3>

        <div className="rounded-3xl bg-surface p-4 min-h-[200px]">
          {habits.length === 0 ? (
            <div className="empty-state">
              <p className="text-text-secondary">Noch keine Habits</p>
            </div>
          ) : (
            <div className="space-y-3">
              {habits.map((habit) => (
                <div
                  key={habit.id}
                  className="flex items-center justify-between p-3 rounded-2xl bg-surface-hover"
                >
                  <div className="flex items-center gap-3">
                    <span className="text-2xl">{habit.emoji}</span>
                    <span className="font-medium">{habit.name}</span>
                  </div>
                  <button
                    onClick={() => handleDeleteHabit(habit.id)}
                    className="p-2 rounded-full hover:bg-red-100 text-red-500 transition-colors"
                    aria-label="Habit löschen"
                    title="Löschen"
                  >
                    🗑️
                  </button>
                </div>
              ))}
            </div>
          )}

          <button
            data-testid="habit-add"
            onClick={() => setShowAddModal(true)}
            className="w-full mt-4 btn btn-primary"
          >
            + neues Habit
          </button>
        </div>
      </section>

      {/* Add Habit Modal */}
      {showAddModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50">
          <div className="bg-surface rounded-3xl p-6 w-full max-w-sm">
            <h3 className="text-xl font-bold mb-4">Neues Habit</h3>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium mb-2">Name</label>
                <input
                  data-testid="habit-name"
                  type="text"
                  value={newHabitName}
                  onChange={(e) => setNewHabitName(e.target.value)}
                  placeholder="z.B. Wasser trinken"
                  className="w-full p-3 rounded-2xl border border-border"
                  autoFocus
                />
              </div>

              <div>
                <label className="block text-sm font-medium mb-2">Emoji</label>
                <div className="flex gap-2 justify-center">
                  {MOOD_EMOJIS.map((emoji) => (
                    <button
                      key={emoji}
                      onClick={() => setSelectedEmoji(emoji)}
                      className={`text-3xl p-2 rounded-2xl transition-all ${
                        selectedEmoji === emoji ? 'bg-border ring-2 ring-accent' : 'hover:bg-surface-hover'
                      }`}
                    >
                      {emoji}
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium mb-2">Farbe</label>
                <div className="flex gap-2">
                  {colorOptions.map((color) => (
                    <button
                      key={color.name}
                      onClick={() => setSelectedColor(color.name)}
                      className={`w-10 h-10 rounded-full flex items-center justify-center transition-all ${
                        selectedColor === color.name ? 'ring-2 ring-offset-2 ring-accent' : 'hover:scale-110'
                      }`}
                      style={{ backgroundColor: MOOD_COLORS[colorOptions.indexOf(color)] }}
                      title={color.name}
                    >
                      {color.emoji}
                    </button>
                  ))}
                </div>
              </div>

              <div className="flex gap-3 mt-6">
                <button
                  onClick={() => setShowAddModal(false)}
                  className="flex-1 py-3 rounded-2xl font-medium hover:bg-border"
                >
                  Abbrechen
                </button>
                <button
                  data-testid="habit-save"
                  onClick={handleAddHabit}
                  className="flex-1 py-3 rounded-2xl font-medium bg-accent text-white"
                >
                  Speichern
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

