        /* eslint-disable @typescript-eslint/no-unused-vars */
        const statusStore = db.createObjectStore('habitStatus', { keyPath: 'id' })
        statusStore.createIndex('habitId_date', ['habitId', 'date'])
        statusStore.createIndex('date', 'date')
      }

      // Moods Store
      if (!db.objectStoreNames.contains('moods')) {
        /* eslint-disable @typescript-eslint/no-unused-vars */
        const moodsStore = db.createObjectStore('moods', { keyPath: 'id' })
        moodsStore.createIndex('date', 'date')
      }

      // Settings Store
      if (!db.objectStoreNames.contains('settings')) {
        /* eslint-disable @typescript-eslint/no-unused-vars */
        const settingsStore = db.createObjectStore('settings', { keyPath: 'key' })
      }
    }
  })
}

// Helper: UUID generieren
export const generateId = (): string => {
  return crypto.randomUUID()
}

// Settings
export const getTheme = async (): Promise<Theme> => {
  try {
    const db = await openRhythmDB()
    const value = await db.get('settings', 'theme')
    return value?.value || 'system'
  } catch {
    return 'system'
  }
}

export const setTheme = async (theme: Theme) => {
  const db = await openRhythmDB()
  await db.put('settings', { key: 'theme', value: theme })
}

export const getSystemTheme = (): SystemTheme => {
  if (typeof window === 'undefined') return 'light'
  return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'
}

// Habits
export const getAllHabits = async (): Promise<Habit[]> => {
  const db = await openRhythmDB()
  return await db.getAll('habits')
}

export const addHabit = async (habit: Omit<Habit, 'id' | 'createdAt'>): Promise<string> => {
  const db = await openRhythmDB()
  const id = generateId()
  const newHabit = { ...habit, id, createdAt: Date.now() }
  await db.add('habits', newHabit)
  return id
}

export const updateHabit = async (habit: Habit): Promise<void> => {
  const db = await openRhythmDB()
  await db.put('habits', habit)
}

export const deleteHabit = async (id: string): Promise<void> => {
  const db = await openRhythmDB()
  await db.delete('habits', id)
  // Also delete status entries
  const status = await db.getAll('habitStatus')
  const toDelete = status.filter(s => s.habitId === id).map(s => s.id)
  for (const id of toDelete) {
    await db.delete('habitStatus', id)
  }
}

// Habit Status
export const getHabitStatus = async (habitId: string, date: string): Promise<HabitStatus | undefined> => {
  const db = await openRhythmDB()
  const tx = db.transaction('habitStatus', 'readonly')
  const store = tx.objectStore('habitStatus')
  const index = store.index('habitId_date')
  const key = [habitId, date]
  const value = await index.get(key)
  return value
}

export const setHabitStatus = async (habitId: string, date: string, completed: boolean): Promise<void> => {
  const db = await openRhythmDB()
  const existing = await getHabitStatus(habitId, date)

  if (existing) {
    await db.put('habitStatus', {
      ...existing,
      completed,
      timestamp: Date.now()
    })
  } else {
    await db.add('habitStatus', {
      id: generateId(),
      habitId,
      date,
      completed,
      timestamp: Date.now()
    })
  }
}

// Streaks berechnen
export const calculateStreaks = async (habitId: string): Promise<{ current: number }> => {
  const db = await openRhythmDB()
  const status = await db.getAll('habitStatus')

  const habitStatuses = status
    .filter(s => s.habitId === habitId && s.completed)
    .map(s => s.date)
    .sort()

  if (habitStatuses.length === 0) return { current: 0 }

  let current = 0
  let streak = 0
  const today = getTodayString()
  const yesterday = getYesterdayString()

  // Aktuelle Serie berechnen (ab heute oder gestern rückwärts)
  const todayIndex = habitStatuses.indexOf(today)
  const yesterdayIndex = habitStatuses.indexOf(yesterday)

  if (todayIndex !== -1 || yesterdayIndex !== -1) {
    // Wir sind in einer aktiven Serie
    let checkDate = today
    if (todayIndex === -1) checkDate = yesterday

    while (true) {
      if (habitStatuses.includes(checkDate)) {
        streak++
        const date = new Date(checkDate)
        date.setDate(date.getDate() - 1)
        checkDate = date.toISOString().split('T')[0]
      } else {
        break
      }
    }
    current = streak
  }

  return { current }
}

// Moods
export const getMoodForDate = async (date: string): Promise<Mood | undefined> => {
  const db = await openRhythmDB()
  return await db.get('moods', date)
}

export const setMood = async (date: string, value: number, note?: string): Promise<void> => {
  const db = await openRhythmDB()
  const existing = await db.get('moods', date)

  if (existing) {
    await db.put('moods', {
      ...existing,
      value,
      note,
      timestamp: Date.now()
    })
  } else {
    await db.add('moods', {
      id: date,
      date,
      value,
      note,
      timestamp: Date.now()
    })
  }
}

export const getMoodHistory = async (days: number): Promise<Mood[]> => {
  const db = await openRhythmDB()
  const allMoods = await db.getAll('moods')

  const cutoff = new Date()
  cutoff.setDate(cutoff.getDate() - days)

  return allMoods
    .filter(m => new Date(m.date) >= cutoff)
    .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime())
}

// Heute's Habits mit Status
export const getTodayHabits = async (): Promise<(Habit & { completed: boolean })[]> => {
  const db = await openRhythmDB()
  const habits = await db.getAll('habits')

  const results: (Habit & { completed: boolean })[] = []

  for (const habit of habits) {
    const status = await getHabitStatus(habit.id, getTodayString())
    results.push({
      ...habit,
      completed: status?.completed || false
    })
  }

  return results
}

// Woche's Daten für Chart
export const getWeekData = async (): Promise<{ date: string; completed: number; mood: number | null }[]> => {
  const db = await openRhythmDB()
  const weekData: { [key: string]: { completed: number; mood: number | null } } = {}

  // Letzte 7 Tage initialisieren
  for (let i = 6; i >= 0; i--) {
    const date = new Date()
    date.setDate(date.getDate() - i)
    const dateStr = date.toISOString().split('T')[0]
    weekData[dateStr] = { completed: 0, mood: null }
  }

  // Status für alle Habits der letzten 7 Tage zählen
  const status = await db.getAll('habitStatus')
  for (const s of status) {
    if (weekData[s.date] !== undefined && s.completed) {
      weekData[s.date].completed++
    }
  }

  // Moods für die letzten 7 Tage laden
  const moods = await db.getAll('moods')
  for (const m of moods) {
    if (weekData[m.date] !== undefined) {
      weekData[m.date].mood = m.value
    }
  }

  return Object.entries(weekData)
    .map(([date, data]) => ({ date, ...data }))
    .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime())
}

import { useState, useEffect, useCallback } from 'react'
import { useNavigate } from 'react-router-dom'
import { getTodayHabits, setHabitStatus, calculateStreaks } from '../db'
import type { Habit } from '../db'
import './App.css'

export default function TodayScreen() {
  const navigate = useNavigate()
  const [habits, setHabits] = useState<(Habit & { completed: boolean })[]>([])
  const [loading, setLoading] = useState(true)

  // Aktuelle Habits laden
  const loadHabits = useCallback(async () => {
    try {
      const loadedHabits = await getTodayHabits()
      setHabits(loadedHabits)
    } catch (error) {
      console.error('Fehler beim Laden der Habits:', error)
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    loadHabits()
  }, [loadHabits])

  // Fortschritt berechnen
  const progress = habits.reduce((acc, habit) => acc + (habit.completed ? 1 : 0), 0)
  const total = habits.length

  // Habit abhaken/abhaken
  const toggleHabit = async (habitId: string, currentStatus: boolean) => {
    try {
      const date = new Date().toISOString().split('T')[0]
      await setHabitStatus(habitId, date, !currentStatus)
      await loadHabits()
    } catch (error) {
      console.error('Fehler beim Ändern des Status:', error)
    }
  }

  // Navigiere zur Einstellungen zum Hinzufügen
  const handleAddHabit = () => {
    navigate('/settings')
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="text-text-secondary">Laden...</div>
      </div>
    )
  }

  return (
    <div className="p-4 space-y-6">
      {/* Header mit Datum und Fortschritt */}
      <header className="mb-6">
        <div className="text-4xl font-bold text-text mb-2">
          {new Date().toLocaleDateString('de-DE', { 
            weekday: 'long', 
            day: 'numeric', 
            month: 'long' 
          })}
        </div>
        <div 
          data-testid="progress"
          className="text-2xl font-semibold text-accent"
        >
          {total > 0 ? `${progress} von ${total}` : '0 von 0'}
        </div>
      </header>

      {/* Habits Liste */}
      <div className="space-y-3">
        {habits.length === 0 ? (
          <div className="empty-state">
            <div className="text-6xl mb-4">✊</div>
            <h3 className="text-xl font-semibold mb-2">Keine Habits</h3>
            <p>Erstelle dein erstes Habit und starte durch!</p>
            <button
              data-testid="habit-add"
              onClick={handleAddHabit}
              className="mt-6 btn btn-primary"
            >
              + Habit hinzufügen
            </button>
          </div>
        ) : (
          habits.map((habit) => (
            <HabitItem
              key={habit.id}
              habit={habit}
              onToggle={() => toggleHabit(habit.id, habit.completed)}
            />
          ))
        )}
      </div>

      {/* Add Habit Button */}
      <button
        data-testid="habit-add"
        onClick={handleAddHabit}
        className="w-full btn btn-primary"
      >
        + weiteres Habit
      </button>
    </div>
  )
}

// Einzelnes Habit Item
interface HabitItemProps {
  habit: Habit & { completed: boolean }
  onToggle: () => void
}

function HabitItem({ habit, onToggle }: HabitItemProps) {
  const [streaks, setStreaks] = useState({ current: 0 })

  useEffect(() => {
    calculateStreaks(habit.id).then(setStreaks)
  }, [habit.id, habit.completed])

  return (
    <div
      data-testid="habit-item"
      className={`flex items-center justify-between p-4 rounded-3xl border-2 transition-all duration-300 ${
        habit.completed 
          ? 'border-border bg-surface opacity-60' 
          : 'border-transparent bg-surface hover:shadow-soft'
      }`}
    >
      <div className="flex items-center gap-4">
        {/* Habit Icon/Emoji */}
        <div className="text-3xl select-none">{habit.emoji}</div>

        <div>
          <div className="font-semibold text-lg">{habit.name}</div>
          <div 
            data-testid="habit-streak"
            className="text-sm text-text-secondary flex items-center gap-2"
          >
            <span className="flex items-center gap-1">
              🔥 {streaks.current}
            </span>
            <span className="opacity-50">•</span>
            <span className="flex items-center gap-1">
              🏆 {streaks.current + 1}
            </span>
          </div>
        </div>
      </div>

      {/* Toggle Button */}
      <button
        data-testid="habit-toggle"
        onClick={onToggle}
        aria-pressed={habit.completed}
        className={`w-14 h-8 rounded-full p-1 transition-all duration-300 ${
          habit.completed ? 'bg-accent' : 'bg-border'
        }`}
      >
        <div 
          className={`w-6 h-6 rounded-full bg-white shadow-md transition-transform duration-300 ${
            habit.completed ? 'translate-x-6' : 'translate-x-0'
          }`}
        />
      </button>
    </div>
  )
}

import { useState, useEffect, useCallback } from 'react'
import { getWeekData, setMood } from '../db'
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts'
import './App.css'

export default function WeekScreen() {
  const [data, setData] = useState<{ date: string; completed: number; mood: number | null }[]>([])
  const [loading, setLoading] = useState(true)

  // Woche's Daten laden
  const loadData = useCallback(async () => {
    try {
      const weekData = await getWeekData()
      setData(weekData)
    } catch (error) {
      console.error('Fehler beim Laden der Woche:', error)
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    loadData()
  }, [loadData])

  // Mood setzen
  const handleMoodSelect = async (value: number) => {
    try {
      const date = new Date().toISOString().split('T')[0]
      await setMood(date, value)
      await loadData()
    } catch (error) {
      console.error('Fehler beim Setzen der Stimmung:', error)
    }
  }

  // Heute's Stimmung
  const todayMood = data.length > 0 ? data[data.length - 1]?.mood : null

  // Datum formatieren
  const formatDate = (dateStr: string) => {
    const date = new Date(dateStr)
    return date.toLocaleDateString('de-DE', { weekday: 'short' })
  }

  // Mood Farbe
  const getMoodColor = (value: number) => {
    const colors = ['#D62828', '#F77F00', '#FCAF45', '#2A9D8F', '#2A9D8F']
    return colors[value - 1]
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="text-text-secondary">Laden...</div>
      </div>
    )
  }

  return (
    <div className="p-4 space-y-6">
      <h2 className="text-2xl font-bold mb-6">Woche</h2>

      {/* Heute's Stimmung */}
      <section>
        <h3 className="text-lg font-semibold mb-3">Heute's Stimmung</h3>
        <div className="flex justify-between items-center p-4 rounded-3xl bg-surface">
          <div className="flex flex-col gap-1">
            <p className="text-sm text-text-secondary">Wie fühlst du dich heute?</p>
            <div className="flex gap-2" role="radiogroup" aria-label="Stimmungswahl">
              {[1, 2, 3, 4, 5].map((value) => (
                <button
                  key={value}
                  data-testid={`mood-${value}`}
                  role="radio"
                  aria-checked={todayMood === value}
                  onClick={() => handleMoodSelect(value)}
                  className={`w-12 h-12 rounded-2xl flex items-center justify-center text-2xl transition-all duration-200 ${
                    todayMood === value 
                      ? `scale-110 ring-2 ring-offset-2 ring-accent` 
                      : 'hover:scale-105'
                  }`}
                  style={{
                    backgroundColor: todayMood === value ? getMoodColor(value) : '',
                    color: todayMood === value ? '#FFFFFF' : ''
                  }}
                >
                  {['😡', '😢', '😐', '🙂', '😄'][value - 1]}
                </button>
              ))}
            </div>
          </div>
        </div>
      </section>

      {/* Chart */}
      <section data-testid="week-chart">
        <h3 className="text-lg font-semibold mb-3">Letzte 7 Tage</h3>
        <div className="rounded-3xl bg-surface p-4">
          {data.length === 0 || data.every(d => d.completed === 0 && d.mood === null) ? (
            <div className="empty-state py-8">
              <p>Noch keine Daten für dieses Wochen</p>
            </div>
          ) : (
            <ResponsiveContainer width="100%" height={250}>
              <BarChart data={data} margin={{ top: 20, right: 30, left: 20, bottom: 40 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="rgba(0,0,0,0.1)" />
                <XAxis 
                  dataKey="date" 
                  tickFormatter={formatDate}
                  axisLine={false}
                  tickLine={false}
                  dy={10}
                />
                <YAxis 
                  axisLine={false}
                  tickLine={false}
                  domain={[0, 'auto']}
                  tickCount={6}
                />
                <Tooltip 
                  contentStyle={{ 
                    borderRadius: '12px', 
                    border: 'none',
                    boxShadow: '0 4px 12px rgba(0,0,0,0.1)'
                  }}
                  cursor={{ fill: 'rgba(0,0,0,0.05)' }}
                />
                <Legend />
                <Bar 
                  dataKey="completed" 
                  name="Erledigte Habits" 
                  fill="#346538"
                  radius={[8, 8, 0, 0]}
                  barSize={24}
                />
              </BarChart>
            </ResponsiveContainer>
          )}
        </div>
      </section>
    </div>
  )
}

