  --font-serif: "Lyon Text", "Newsreader", "Playfair Display", serif;

  /* Warm monochrome Palette */
  --color-background: #F7F6F3;
  --color-surface: #FFFFFF;
  --color-surface-hover: #F9F9F8;
  --color-text: #2F3437;
  --color-text-secondary: #787774;
  --color-border: #EAEAEA;
  --color-accent: #346538;

  /* Muted Pastels für Habit-Farben */
  --color-pastel-red: #FDEBEC;
  --color-pastel-red-text: #9F2F2D;
  --color-pastel-blue: #E1F3FE;
  --color-pastel-blue-text: #1F6C9F;
  --color-pastel-green: #EDF3EC;
  --color-pastel-green-text: #346538;
  --color-pastel-yellow: #FBF3DB;
  --color-pastel-yellow-text: #956400;

  /* Radien und Schatten (sehr dezent) */
  --radius-soft: 24px;
  --shadow-soft: 0 2px 8px 0 rgba(0, 0, 0, 0.04);
}

:root {
  font-family: var(--font-sans);
  color: var(--color-text);
  background: var(--color-background);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* Mobile first: schmale Spalte auf Desktop */
#root {
  min-height: 100vh;
  background: var(--color-background);
}

/* Container für zentrierte, schmale Spalte auf Desktop */
.app-container {
  max-width: 480px;
  margin: 0 auto;
  min-height: 100vh;
  background: var(--color-background);
  position: relative;
}

/* Tab-Navigation (Bottom Navigation) */
.bottom-nav {
  position: fixed;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 100%;
  max-width: 480px;
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
  display: flex;
  justify-content: space-around;
  padding: 16px 0;
  box-shadow: 0 -2px 8px 0 rgba(0, 0, 0, 0.04);
}

.nav-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  border-radius: 12px;
  min-width: 60px;
  min-height: 56px;
  font-size: 11px;
  font-weight: 500;
  color: var(--color-text-secondary);
  transition: all 0.2s ease;
}

.nav-item:hover {
  background: var(--color-surface-hover);
}

.nav-item.active {
  color: var(--color-accent);
  font-weight: 600;
}

/* Hauptinhalt mit ausreichend Padding für Bottom-Navigation */
.main-content {
  padding-bottom: 100px;
}

/* Karten-Stil */
.card {
  background: var(--color-surface);
  border-radius: var(--radius-soft);
  box-shadow: var(--shadow-soft);
  padding: 24px;
  margin-bottom: 16px;
}

/* Typografie */
h1, h2, h3 {
  font-family: var(--font-sans);
  font-weight: 600;
  color: var(--color-text);
  line-height: 1.3;
}

h1 { font-size: 28px; margin: 0 0 16px; }
h2 { font-size: 20px; margin: 0 0 12px; }
h3 { font-size: 16px; margin: 0 0 8px; }

p {
  margin: 0 0 8px;
  color: var(--color-text-secondary);
  font-size: 14px;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 12px 24px;
  border-radius: 12px;
  font-size: 15px;
