  background: #1a1d1f;
}

.btn-icon {
  padding: 12px;
  min-width: 48px;
  min-height: 48px;
}

/* Form Elements */
input, select {
  width: 100%;
  padding: 12px 16px;
  border-radius: 12px;
  border: 1px solid var(--color-border);
  background: var(--color-surface);
  font-size: 15px;
  font-family: var(--font-sans);
  color: var(--color-text);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

input:focus, select:focus {
  outline: none;
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px rgba(52, 101, 56, 0.1);
}

/* Focus-Styles für Tastatur-Navigation - wichtig für Barrierefreiheit */
* {
  outline-color: var(--color-accent);
}

*::-moz-focus-inner {
  border: none;
}

