@import "tailwindcss";

:root {
  --font-sans: -apple-system, BlinkMacSystemFont, "SF Pro Display", "Segoe UI", Roboto, Helvetica, Arial, sans-serif;

  --color-background: #F7F6F3;
  --color-surface: #FFFFFF;
  --color-surface-hover: #F9F9F8;
  --color-text: #2F3437;
  --color-text-secondary: #787774;
  --color-border: #EAEAEA;
  --color-accent: #346538;

  --radius-soft: 24px;
}

:root {
  font-family: var(--font-sans);
  color: var(--color-text);
  background: var(--color-background);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

#root {
  min-height: 100vh;
  background: var(--color-background);
}

.app-container {
  max-width: 480px;
  margin: 0 auto;
  min-height: 100vh;
  background: var(--color-background);
  position: relative;
}

.bottom-nav {
  position: fixed;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 100%;
  max-width: 480px;
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
  display: flex;
  justify-content: space-around;
  padding: 16px 0;
  box-shadow: 0 -2px 8px 0 rgba(0, 0, 0, 0.04);
}

.nav-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  border-radius: 12px;
  min-width: 60px;
  min-height: 56px;
  font-size: 11px;
  font-weight: 500;
  color: var(--color-text-secondary);
  transition: all 0.2s ease;
}

.nav-item:hover {
  background: var(--color-surface-hover);
}

.nav-item.active {
  color: var(--color-accent);
  font-weight: 600;
}

.main-content {
  padding-bottom: 100px;
}

.card {
  background: var(--color-surface);
  border-radius: var(--radius-soft);
  box-shadow: 0 2px 8px 0 rgba(0, 0, 0, 0.04);
  padding: 24px;
  margin-bottom: 16px;
}

h1, h2, h3 {
  font-family: var(--font-sans);
  font-weight: 600;
  color: var(--color-text);
  line-height: 1.3;
}

h1 { font-size: 28px; margin: 0 0 16px; }
h2 { font-size: 20px; margin: 0 0 12px; }
h3 { font-size: 16px; margin: 0 0 8px; }

p {
  margin: 0 0 8px;
  color: var(--color-text-secondary);
  font-size: 14px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 12px 24px;
  border-radius: 12px;
  font-size: 15px;
  font-weight: 500;
  font-family: var(--font-sans);
  cursor: pointer;
  transition: all 0.2s ease;
  border: none;
}

.btn-primary {
  background: var(--color-text);
  color: #FFFFFF;
}

.btn-primary:hover {
  background: #1a1d1f;
}

.btn-icon {
  padding: 12px;
  min-width: 48px;
  min-height: 48px;
}

input, select {
  width: 100%;
  padding: 12px 16px;
  border-radius: 12px;
  border: 1px solid var(--color-border);
  background: var(--color-surface);
  font-size: 15px;
  font-family: var(--font-sans);
  color: var(--color-text);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

input:focus, select:focus {
  outline: none;
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px rgba(52, 101, 56, 0.1);
}

* {
  outline-color: var(--color-accent);
}

*::-moz-focus-inner {
  border: none;
}

::-webkit-scrollbar {
  width: 6px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background: var(--color-border);
  border-radius: 3px;
}

@media (prefers-color-scheme: dark) {
  :root {
    --color-background: #1a1b1d;
    --color-surface: #25272a;
    --color-surface-hover: #2d2f33;
    --color-text: #E5E7EB;
    --color-text-secondary: #9CA3AF;
    --color-border: #373A40;
    --color-accent: #4B9E5F;
  }

  .bottom-nav {
    background: var(--color-surface);
    border-top: 1px solid var(--color-border);
    box-shadow: 0 -2px 8px 0 rgba(0, 0, 0, 0.3);
  }

  input, select {
    background: var(--color-surface);
    border-color: var(--color-border);
    color: var(--color-text);
  }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

.empty-state {
  text-align: center;
  padding: 64px 24px;
  color: var(--color-text-secondary);
}

.empty-state p {
  margin: 8px 0;
}

