1: #!/usr/bin/env node
2: // verify.mjs – Smoke-Test für die Habit-Tracker-PWA "Rhythm" (LLM-Bench).
3: //
4: // Aufruf:   node verify.mjs [URL]      (Standard: http://localhost:4173)
5: // Optionen: --json   Ergebnis zusätzlich als JSON auf stdout (letzte Zeile)
6: // Umgebung: CHROME_PATH=/pfad/zu/chrome   statt des installierten Google Chrome
7: //
8: // Das Skript öffnet die laufende App (z. B. `npm run preview`) in einem headless Chrome bei 375 px Breite,
9: // bedient sie wie ein Nutzer und meldet pro Prüfung PASS oder FAIL. Es ändert nichts an der App.
10: // Die App muss dafür die in der Aufgabe genannten data-testid-Attribute und aria-pressed setzen.
11: 
12: import { chromium } from 'playwright-core';
13: 
14: const args = process.argv.slice(2);
15: const wantJson = args.includes('--json');
16: const url = args.find((a) => !a.startsWith('--')) ?? 'http://localhost:4173';
17: const origin = new URL(url).origin;
18: 
19: const VIEWPORT = { width: 375, height: 812 };
20: const T = 4000; // Timeout pro Nutzeraktion in ms
21: 
22: const results = [];
23: const warnings = [];
24: const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
25: const assert = (cond, msg) => {
26:   if (!cond) throw new Error(msg);
27: };
28: 
29: async function check(name, fn) {
30:   try {
31:     const note = await fn();
32:     results.push({ name, ok: true, note: note ?? '' });
33:     console.log(`PASS  ${name}${note ? '  (' + note + ')' : ''}`);
34:   } catch (e) {
35:     const msg = String(e.message ?? e).split('\n')[0].slice(0, 400);
36:     results.push({ name, ok: false, note: msg });
37:     console.log(`FAIL  ${name}\n        ${msg}`);
38:   }
39: }
40: 
41: const launchOpts = process.env.CHROME_PATH
42:   ? { executablePath: process.env.CHROME_PATH }
43:   : { channel: 'chrome' };
44: 
45: let browser;
46: try {
47:   browser = await chromium.launch({ headless: true, ...launchOpts });
48: } catch (e) {
49:   console.error('Chrome konnte nicht gestartet werden: ' + String(e.message).split('\n')[0]);
50:   console.error('Tipp: Google Chrome installieren oder CHROME_PATH setzen.');
51:   process.exit(2);
52: }
53: 
54: async function newSession({ colorScheme = 'light' } = {}) {
55:   const ctx = await browser.newContext({
56:     viewport: VIEWPORT,
57:     locale: 'de-DE',
58:     colorScheme,
59:     serviceWorkers: 'allow',
60:   });
61:   ctx.setDefaultTimeout(T);
62:   const page = await ctx.newPage();
63:   const errors = [];
64:   const sameOrigin = (u) => {
65:     try {
66:       const x = new URL(u);
67:       return x.origin === origin && x.pathname !== '/favicon.ico';
68:     } catch {
69:       return false;
70:     }
71:   };
72:   page.on('pageerror', (e) => errors.push(`JS-Fehler: ${e.message}`));
73:   page.on('console', (m) => {
74:     if (m.type() === 'error' && sameOrigin(m.location().url || url)) errors.push(`console.error: ${m.text()}`);
75:   });
76:   page.on('requestfailed', (r) => {
77:     if (sameOrigin(r.url())) errors.push(`Request fehlgeschlagen: ${r.url()}`);
78:   });
79:   page.on('response', (r) => {
80:     if (sameOrigin(r.url()) && r.status() >= 400) errors.push(`HTTP ${r.status()}: ${r.url()}`);
81:   });
82:   return { ctx, page, errors };
83: }
84: 
85: const tid = (page, id) => page.getByTestId(id);
86: async function go(page, navId) {
87:   await tid(page, navId).first().click({ timeout: T });
88:   await sleep(350);
89: }
90: async function onScreens(page, id, screens = ['nav-today', 'nav-settings', 'nav-week']) {
91:   for (const s of screens) {
92:     try {
93:       await go(page, s);
94:     } catch {
95:       continue;
96:     }
97:     if ((await tid(page, id).count()) > 0) return s;
98:   }
99:   return null;
100: }
101: const bodyText = (page) => page.evaluate(() => document.body.innerText.replace(/\s+/g, ' ').trim());
102: const reload = async (page) => {
103:   await page.reload({ waitUntil: 'load' });
104:   await sleep(600);
105: };
106: const pressed = async (loc) => {
107:   const v = (await loc.getAttribute('aria-pressed')) ?? (await loc.getAttribute('aria-checked'));
108:   return v === 'true';
109: };
110: const progress = async (page) => {
111:   const txt = (await tid(page, 'progress').first().innerText()).replace(/\s+/g, ' ');
112:   const m = txt.match(/(\d+)\s*von\s*(\d+)/i);
113:   assert(m, `Fortschritt "${txt}" passt nicht zu "X von Y"`);
114:   return { done: +m[1], total: +m[2], txt };
115: };
116: // effektive Hintergrundluminanz (0 = schwarz, 1 = weiß) links in der Bildschirmmitte
117: const luminance = (page) =>
118:   page.evaluate(() => {
119:     const c = document.createElement('canvas');
120:     c.width = c.height = 1;
121:     const g = c.getContext('2d', { willReadFrequently: true });
122:     const chain = [];
123:     for (let el = document.elementFromPoint(2, window.innerHeight / 2); el; el = el.parentElement) chain.push(el);
124:     // Hintergrund von <body> wird vom Browser auf die ganze Fläche übertragen, auch wenn der Punkt unter dem Body liegt
125:     chain.push(document.body, document.documentElement);
126:     for (const el of chain) {
127:       const col = getComputedStyle(el).backgroundColor;
128:       g.clearRect(0, 0, 1, 1);
129:       g.fillStyle = '#000';
130:       g.fillStyle = col;
131:       g.fillRect(0, 0, 1, 1);
132:       const [r, gr, b, a] = g.getImageData(0, 0, 1, 1).data;
133:       if (a > 250) return (0.2126 * r + 0.7152 * gr + 0.0722 * b) / 255;
134:     }
135:     return 1;
136:   });
137: 
138: console.log(`Smoke-Test gegen ${url}  (Viewport ${VIEWPORT.width}x${VIEWPORT.height})\n`);
139: 
140: // ---------------------------------------------------------------- Sitzung 1: frischer Zustand
141: const s1 = await newSession();
142: const { page } = s1;
143: 
144: await check('Seite lädt und rendert Inhalt', async () => {
145:   await page.goto(url, { waitUntil: 'load' });
146:   await sleep(800);
147:   const t = await bodyText(page);
148:   assert(t.length > 10, 'Seite bleibt (fast) leer');
149: });
150: 
151: await check('Keine JS-Fehler und keine fehlgeschlagenen Requests beim Laden', async () => {
152:   assert(s1.errors.length === 0, s1.errors.slice(0, 3).join(' | '));
153: });
154: 
155: await check('Stylesheet ist verarbeitet (keine rohen Direktiven)', async () => {
156:   const css = await page.evaluate(async () => {
157:     const out = [];
158:     for (const l of document.querySelectorAll('link[rel="stylesheet"]')) {
159:       if (new URL(l.href).origin !== location.origin) continue;
160:       out.push(await (await fetch(l.href)).text());
161:     }
162:     for (const s of document.querySelectorAll('style')) out.push(s.textContent || '');
163:     return out.join('\n');
164:   });
165:   assert(css.length > 0, 'Keine eigenen Stylesheets gefunden');
166:   const m = css.match(/@theme\b|@tailwind\b|@import\s+["']tailwindcss|@apply\b/);
167:   assert(!m, `Stylesheet enthält unverarbeitete Direktive "${m?.[0]}"`);
168: });
169: 
170: await check('Bottom-Navigation: 3 Tabs sichtbar am unteren Bildschirmrand', async () => {
171:   const boxes = [];
172:   for (const id of ['nav-today', 'nav-week', 'nav-settings']) {
173:     const loc = tid(page, id).first();
174:     assert((await tid(page, id).count()) > 0, `data-testid="${id}" nicht gefunden`);
175:     assert(await loc.isVisible(), `${id} nicht sichtbar`);
176:     boxes.push({ id, ...(await loc.boundingBox()) });
177:   }
178:   for (const b of boxes) {
179:     assert(b.y + b.height <= VIEWPORT.height + 1, `${b.id} liegt unterhalb des sichtbaren Bereichs (y=${Math.round(b.y)})`);
180:     assert(b.y > VIEWPORT.height * 0.75, `${b.id} liegt nicht am unteren Rand (y=${Math.round(b.y)})`);
181:   }
182:   const ys = boxes.map((b) => Math.round(b.y));
183:   assert(Math.max(...ys) - Math.min(...ys) < 12, 'Tabs stehen nicht in einer Zeile');
184: });
185: 
186: await check('Tab-Navigation: Klick wechselt den Bildschirm', async () => {
187:   const today0 = await bodyText(page);
188:   await go(page, 'nav-week');
189:   const week = await bodyText(page);
190:   assert(week !== today0, 'Klick auf "nav-week" ändert nichts am Inhalt');
191:   await go(page, 'nav-settings');
192:   const sett = await bodyText(page);
193:   assert(sett !== week, 'Klick auf "nav-settings" ändert nichts am Inhalt');
194:   await go(page, 'nav-today');
195:   const back = await bodyText(page);
196:   assert(back !== sett, 'Klick auf "nav-today" ändert nichts am Inhalt');
197: });
198: 
199: await check('Kein horizontales Scrollen, Seitenbreite passt in 375 px', async () => {
200:   const w = await page.evaluate(() => document.documentElement.scrollWidth);
201:   assert(w <= VIEWPORT.width + 1, `Seite ist ${w}px breit`);
202: });
203: 
204: await check('Touch-Ziele mindestens 44x44 px (Tabs)', async () => {
205:   const small = [];
206:   for (const id of ['nav-today', 'nav-week', 'nav-settings']) {
207:     const b = await tid(page, id).first().boundingBox();
208:     if (!b || b.width < 44 || b.height < 44) small.push(`${id}=${Math.round(b?.width)}x${Math.round(b?.height)}`);
209:   }
210:   assert(small.length === 0, small.join(', '));
211: });
212: 
213: await check('Habit anlegen (Name, Speichern) und erscheint auf dem Heute-Screen', async () => {
214:   const where = await onScreens(page, 'habit-add');
215:   assert(where, 'data-testid="habit-add" auf keinem Bildschirm gefunden');
216:   for (const name of ['Wasser trinken', 'Lesen']) {
217:     await tid(page, 'habit-add').first().click({ timeout: T });
218:     await sleep(250);
219:     await tid(page, 'habit-name').first().fill(name, { timeout: T });
220:     await tid(page, 'habit-save').first().click({ timeout: T });
221:     await sleep(400);
222:   }
223:   await go(page, 'nav-today');
224:   const n = await tid(page, 'habit-item').count();
