174: export const calculateStreaks = async (habitId: string): Promise<{ current: number }> => {
175:   const db = await openRhythmDB()
176:   const status = await db.getAll('habitStatus')
177:   
178:   const habitStatuses = status
179:     .filter(s => s.habitId === habitId && s.completed)
180:     .map(s => s.date)
181:     .sort()
182:   
183:   if (habitStatuses.length === 0) return { current: 0 }
184:   
185:   let current = 0
186:   let streak = 0
187:   const today = getTodayString()
188:   const yesterday = getYesterdayString()
189:   
190:   // Aktuelle Serie berechnen (ab heute oder gestern rückwärts)
191:   const todayIndex = habitStatuses.indexOf(today)
192:   const yesterdayIndex = habitStatuses.indexOf(yesterday)
193:   
194:   if (todayIndex !== -1 || yesterdayIndex !== -1) {
195:     // Wir sind in einer aktiven Serie
196:     let checkDate = today
197:     if (todayIndex === -1) checkDate = yesterday
198:     
199:     while (true) {
200:       if (habitStatuses.includes(checkDate)) {
201:         streak++
202:         const date = new Date(checkDate)
203:         date.setDate(date.getDate() - 1)
204:         checkDate = date.toISOString().split('T')[0]
205:       } else {
206:         break
207:       }
208:     }
209:     current = streak
210:   }
211:   
212:   return { current }
213: }
