221: export const setMood = async (date: string, value: number, note?: string): Promise<void> => {
222:   const db = await openRhythmDB()
223:   const existing = await db.get('moods', date)
224:   
225:   if (existing) {
226:     await db.put('moods', {
227:       ...existing,
228:       value,
229:       note,
230:       timestamp: Date.now()
231:     })
232:   } else {
233:     await db.add('moods', {
234:       id: date,
235:       date,
236:       value,
237:       note,
238:       timestamp: Date.now()
239:     })
240:   }
241: }
