243: export const getMoodHistory = async (days: number): Promise<Mood[]> => {
244:   const db = await openRhythmDB()
245:   const allMoods = await db.getAll('moods')
246:   
247:   const cutoff = new Date()
248:   cutoff.setDate(cutoff.getDate() - days)
249:   
250:   return allMoods
251:     .filter(m => new Date(m.date) >= cutoff)
252:     .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime())
253: }
