255: // Heute's Habits mit Status
256: export const getTodayHabits = async (): Promise<(Habit & { completed: boolean })[]> => {
257:   const db = await openRhythmDB()
258:   const habits = await db.getAll('habits')
259:   
260:   const results: (Habit & { completed: boolean })[] = []
261:   
262:   for (const habit of habits) {
263:     const status = await getHabitStatus(habit.id, getTodayString())
264:     results.push({
265:       ...habit,
266:       completed: status?.completed || false
267:     })
268:   }
269:   
270:   return results
271: }
