  const after100 = await page.evaluate(() => document.body.innerHTML);
  console.log('After 100ms - has habit-name:', after100.includes('data-testid="habit-name"'));

  await sleep(500);
  const after500 = await page.evaluate(() => document.body.innerHTML);
