276:   const weekData: { [key: string]: { completed: number; mood: number | null } } = {}
277:   
278:   // Letzte 7 Tage initialisieren
279:   for (let i = 6; i >= 0; i--) {
280:     const date = new Date()
281:     date.setDate(date.getDate() - i)
282:     const dateStr = date.toISOString().split('T')[0]
283:     weekData[dateStr] = { completed: 0, mood: null }
284:   }
285:   
286:   // Status für alle Habits der letzten 7 Tage zählen
287:   const status = await db.getAll('habitStatus')
288:   for (const s of status) {
289:     if (weekData[s.date] !== undefined && s.completed) {
290:       weekData[s.date].completed++
291:     }
292:   }
293:   
294:   // Moods für die letzten 7 Tage laden
295:   const moods = await db.getAll('moods')
296:   for (const m of moods) {
297:     if (weekData[m.date] !== undefined) {
298:       weekData[m.date].mood = m.value
299:     }
